export const CODEX_SUMMARIES: Record<string, string> = {
  // ── EUROPE ──────────────────────────────────────────────────────────────────
  AL: "Albania is a small Balkan nation on the Adriatic and Ionian coasts of southeastern Europe, bordered by Montenegro, Kosovo, North Macedonia, and Greece. Once one of the most isolated countries in the world under communist rule until 1991, it has since opened significantly to the wider world. The country is known for its ancient Illyrian heritage, its distinctive double-headed eagle national symbol, and its well-preserved Ottoman-era cities such as UNESCO-listed Gjirokastër.",
  AD: "Andorra is a tiny microstate nestled in the Pyrenean mountains between France and Spain, one of Europe's smallest countries. It has been jointly governed as a co-principality by the French head of state and the Bishop of Urgell since 1278, an arrangement unique in the modern world. Despite its small size, Andorra is a popular destination known for duty-free shopping, skiing, and spectacular mountain scenery.",
  AT: "Austria is a landlocked country in Central Europe known for its alpine scenery, imperial architecture, and extraordinary musical heritage. For centuries it was the centre of the Habsburg Empire, one of Europe's most powerful dynasties, which shaped the culture of the entire continent. Vienna, the capital, was home to Mozart, Beethoven, Schubert, Brahms, and Mahler, and remains one of the world's preeminent cultural cities.",
  BY: "Belarus is a landlocked country in Eastern Europe bordered by Russia, Ukraine, Poland, Lithuania, and Latvia, maintaining close political and economic ties with Russia. Minsk, the capital, was almost entirely destroyed during World War II and was meticulously rebuilt in an imposing Soviet architectural style with wide boulevards and grand public squares. The country has a rich tradition of folk art, weaving, and woodcraft.",
  BE: "Belgium is a small but densely populated country in Western Europe that serves as the de facto capital of the European Union, hosting the EU's major institutions in Brussels. The country is divided into three linguistic communities — Dutch-speaking Flanders, French-speaking Wallonia, and a small German-speaking area — giving it a complex federal structure. Belgium is celebrated globally for its chocolate, beer, waffles, and its rich tradition of comic art.",
  BA: "Bosnia and Herzegovina is a country in the western Balkans with a complex administrative structure established by the 1995 Dayton Agreement following the Bosnian War. The country is home to a mix of Bosniak, Serb, and Croat communities sharing a mountainous, landlocked landscape threaded with rivers. Sarajevo, the capital, famously hosted the 1984 Winter Olympics and is known for its blend of Ottoman, Austro-Hungarian, and socialist architectural heritage.",
  BG: "Bulgaria is a country in southeastern Europe on the Black Sea coast with one of the longest recorded national histories in Europe, having been established as a kingdom in 681 AD. The Cyrillic alphabet, now used by hundreds of millions of people, was developed by Bulgarian monks Saints Cyril and Methodius in the 9th century. Bulgaria is known for its rose oil production, ancient Thracian treasures, Black Sea resorts, and UNESCO-listed Rila Monastery.",
  HR: "Croatia stretches along the eastern Adriatic Sea and is known for its dramatic coastline, more than a thousand islands, and well-preserved medieval cities. Dubrovnik, encircled by massive limestone walls, is one of Europe's most iconic historic cities and has been a UNESCO World Heritage Site since 1979. Croatia joined the European Union in 2013 and is famous worldwide for the crystalline waterfalls of Plitvice Lakes National Park.",
  CY: "Cyprus is an island nation in the Eastern Mediterranean — the third-largest island in the sea — known as the mythological birthplace of the goddess Aphrodite. The island has been divided since 1974, with the northern portion under Turkish administration and the internationally recognised Republic of Cyprus governing the south. It is famous for its warm climate, ancient ruins, Venetian walls, and the unique copper-coloured map depicted on its national flag.",
  CZ: "The Czech Republic, also called Czechia, is a landlocked Central European country celebrated for its medieval architecture, rich brewing tradition, and wealth of historic towns. Prague, the capital, served as an imperial seat of the Holy Roman Empire and remains one of the best-preserved Gothic and Baroque cities in Europe. Czechoslovakia peacefully dissolved into the Czech Republic and Slovakia in 1993, an event known as the Velvet Divorce.",
  DK: "Denmark is a Nordic nation comprising the Jutland Peninsula and numerous islands, consistently ranking among the world's happiest and most prosperous countries. The Danish flag, the Dannebrog, is the oldest national flag still in use by an independent nation, dating to at least 1370. Denmark is a constitutional monarchy with a long maritime trading tradition, and its territories include Greenland, the world's largest island.",
  EE: "Estonia is one of the three Baltic states on the eastern shore of the Baltic Sea, having re-declared independence from the Soviet Union in 1991 as one of its first republics to do so. It rapidly transformed into one of the world's most digitally advanced societies, pioneering e-government, digital voting, and the concept of e-residency. Tallinn, the capital, has one of the best-preserved medieval old towns in all of Northern Europe.",
  FI: "Finland is a Nordic country bordering Sweden, Norway, and Russia, known for its vast forests, tens of thousands of lakes, and the spectacular aurora borealis. It was part of Sweden for nearly 700 years before becoming a Russian Grand Duchy in 1809 and declaring independence in 1917. Finland consistently ranks at the very top of global happiness, education, and quality-of-life indices.",
  FR: "France is one of the world's most visited countries, attracting around 90 million tourists annually, and a founding member of the European Union and a permanent member of the UN Security Council. It has been a major cultural, philosophical, and political force in Western civilisation for centuries. Paris, the capital, is globally associated with art, fashion, gastronomy, the Eiffel Tower, and some of the world's greatest museums.",
  DE: "Germany is the most populous country in the European Union and the largest economy in Europe, known worldwide for its engineering, automotive industry, and precision manufacturing. Reunified in 1990 after four decades of division, Germany became a leading force in European politics and global trade. Berlin, the capital, is one of Europe's most culturally vibrant cities with a history that spans Prussian grandeur, division, and remarkable reunification.",
  GR: "Greece is widely regarded as the cradle of Western civilisation, birthplace of democracy, Western philosophy, the Olympic Games, and significant foundations of modern literature and science. The country consists of a mountainous mainland peninsula and more than 6,000 islands, of which about 230 are permanently inhabited. Athens, one of the world's oldest cities, has been continuously inhabited for at least 7,000 years and is home to the ancient Acropolis.",
  HU: "Hungary is a landlocked Central European country with a language unrelated to its Slavic and Germanic neighbours, belonging to the Finno-Ugric language family. Budapest, formed by the union of Buda and Pest in 1873, is often called the 'Paris of the East' for its grand boulevards, thermal baths, and ornate parliament building on the Danube. Hungary was a major power within the Austro-Hungarian Empire and joined the European Union in 2004.",
  IS: "Iceland is a Nordic island nation in the North Atlantic, the most sparsely populated country in Europe and one of the most geologically active places on Earth, home to active volcanoes, geysers, hot springs, and vast lava fields. Despite its position near the Arctic Circle, the Gulf Stream keeps its coastal areas relatively mild. Iceland's parliament, the Althing, founded in 930 AD, is the world's oldest parliament still in operation.",
  IE: "Ireland is an island nation in northwestern Europe known for its lush green landscapes, rich literary heritage from writers like Oscar Wilde and James Joyce, and vibrant Celtic culture. The island is divided between the Republic of Ireland and Northern Ireland, which is part of the United Kingdom. Ireland joined the European Economic Community in 1973 and has since become one of Europe's most prosperous economies, home to the European headquarters of many global technology companies.",
  IT: "Italy is a southern European country occupying the boot-shaped peninsula that reaches into the Mediterranean, together with the islands of Sicily and Sardinia. The heart of the ancient Roman Empire and the birthplace of the Renaissance, Italy has shaped Western art, architecture, music, and cuisine more than almost any other nation. It holds more UNESCO World Heritage Sites than any country on Earth, and Rome, the capital, completely surrounds the independent Vatican City. Italy unified into a single kingdom only in 1861.",
  XK: "Kosovo is one of the world's newest countries, having declared independence from Serbia in 2008 following a period of international administration after the 1998-99 conflict. It is recognised by over 100 UN member states and is a predominantly Albanian-populated territory with significant Serbian Orthodox cultural heritage, including medieval monasteries that are UNESCO World Heritage Sites. Pristina is its rapidly developing capital and largest city.",
  LV: "Latvia is one of the three Baltic states, situated between Estonia and Lithuania on the eastern shore of the Baltic Sea. It regained independence from the Soviet Union in 1991 and joined both NATO and the European Union in 2004. Riga, the capital, is the largest city in the Baltic states and is renowned for its outstanding collection of Art Nouveau architecture — the largest concentration of such buildings in the world.",
  LI: "Liechtenstein is a tiny doubly landlocked microstate in Central Europe nestled between Switzerland and Austria, and is one of only two countries in the world entirely surrounded by landlocked countries. Despite covering just 160 square kilometres, it has one of the world's highest per-capita incomes and is a significant international financial centre. Liechtenstein is a constitutional monarchy ruled by the Prince of Liechtenstein and has no airport.",
  LT: "Lithuania is the southernmost and largest of the three Baltic states and was historically the centre of the Grand Duchy of Lithuania, one of the largest states in medieval Europe. It was the first Soviet republic to declare independence in 1990 and joined both NATO and the EU in 2004. Vilnius, the capital, is known for its remarkably well-preserved Baroque old town, a UNESCO World Heritage Site.",
  LU: "Luxembourg is a small landlocked grand duchy in Western Europe, bordered by Belgium, France, and Germany, and is one of the wealthiest countries in the world per capita. It hosts key European Union institutions and is a major centre for European banking and finance. Despite its tiny size, Luxembourg has three official languages — Luxembourgish, French, and German — reflecting its position at the crossroads of European cultures.",
  MT: "Malta is a small Mediterranean archipelago south of Sicily and one of the world's smallest and most densely populated countries. Its strategic location has made it a crossroads of civilisations for millennia, ruled by the Phoenicians, Romans, Arabs, Normans, Knights of St John, French, and British. The island has an extraordinary concentration of prehistoric temples, Baroque architecture, and ancient fortifications, and joined the EU in 2004.",
  MD: "Moldova is a small landlocked country in Eastern Europe bordered by Romania and Ukraine, one of Europe's least visited yet historically fascinating nations. Gaining independence from the Soviet Union in 1991, it navigates the challenge of the breakaway region of Transnistria, which has functioned as a de facto separate state since 1990. Moldova has a long winemaking tradition stretching back thousands of years and is known for producing excellent wines.",
  MC: "Monaco is a tiny city-state on the French Riviera, the world's second-smallest country by area after Vatican City, and the most densely populated sovereign state in the world. Synonymous with luxury, it is home to the famous Monte Carlo Casino, the Formula One Monaco Grand Prix, and a high concentration of the world's wealthiest individuals. The Grimaldi family has ruled Monaco since 1297, making it one of the world's oldest ruling dynasties.",
  ME: "Montenegro is a small Balkan nation on the Adriatic Sea that declared independence from the State Union of Serbia and Montenegro in 2006. Its name means 'Black Mountain' in Italian, referring to the imposing dark peak of Mount Lovćen. The country is known for its dramatic mountain landscape, medieval walled towns, and the stunning Bay of Kotor, sometimes described as Europe's southernmost fjord.",
  NL: "The Netherlands is a densely populated country in Western Europe famous for its flat landscape, extensive canal systems, windmills, tulip fields, and masters of Dutch Golden Age painting such as Rembrandt and Vermeer. A historically significant maritime and trading nation, the Netherlands built a major colonial empire during its 17th-century Golden Age. Amsterdam is the constitutional capital while The Hague is the seat of government and home to the International Court of Justice.",
  MK: "North Macedonia is a small landlocked country in the southern Balkans that was part of Yugoslavia until 1991. A prolonged dispute with Greece over the use of the name 'Macedonia' was resolved in 2019 when it officially became the Republic of North Macedonia. Skopje, the capital, was largely destroyed by a devastating earthquake in 1963 and was rebuilt over subsequent decades, and is home to one of the largest and oldest bazaars in the Balkans.",
  NO: "Norway is a Nordic country occupying the western part of the Scandinavian Peninsula, famous for its dramatic fjords, the aurora borealis, the midnight sun, and a remarkably high standard of living. The country manages one of the world's largest sovereign wealth funds, generated from its offshore oil and gas revenues. Norway has a strong tradition of international peacekeeping and humanitarian aid and consistently ranks among the best countries in the world for human development.",
  PL: "Poland is the largest country in Central Europe by area and population, with a turbulent history shaped by centuries of partition and occupation by neighbouring empires. Warsaw, the capital, was almost entirely destroyed during World War II and was painstakingly rebuilt by its citizens, with the historic centre now a UNESCO World Heritage Site. Poland joined NATO in 1999 and the European Union in 2004 and has become one of Europe's fastest-growing economies.",
  PT: "Portugal occupies the southwestern tip of continental Europe and was once the centre of one of history's most far-reaching maritime empires. Portuguese navigators in the 15th and 16th centuries opened sea routes to Africa, Asia, and the Americas, fundamentally reshaping global trade. Today Portugal is known for its fado music, azulejo tilework, pastel de nata custard tarts, port wine, and is one of the oldest nation-states in Europe.",
  RO: "Romania is a country at the intersection of Central, Eastern, and Southeastern Europe, home to the legendary Transylvania region, the Carpathian Mountains, and the biodiverse Danube Delta. The country emerged dramatically from communist rule in December 1989, when Nicolae Ceaușescu's government was overthrown in the only violent revolution of the Eastern Bloc's 1989 wave. Romania joined the EU in 2007 and is known for its medieval citadels, painted monasteries of Bucovina, and unique folk traditions.",
  RU: "Russia is the world's largest country by land area, spanning eleven time zones and stretching from Eastern Europe across northern Asia to the Pacific Ocean. Moscow, the capital, is one of Europe's largest cities and a major global political, economic, and cultural centre. Russia has an extraordinarily rich literary and artistic heritage, with writers like Tolstoy and Dostoevsky, composers like Tchaikovsky and Stravinsky, and a deep tradition of classical ballet.",
  SM: "San Marino is a landlocked microstate entirely surrounded by Italy, and according to tradition was founded in 301 AD, making it the world's oldest republic still in existence. Its territory consists of the slopes of Mount Titano, topped by three medieval fortified towers that have overlooked the surrounding Italian plain for centuries. Despite being completely surrounded by Italian territory, San Marino maintains its own government, passport, and distinct national identity.",
  RS: "Serbia is a landlocked Balkan country that was historically the dominant republic within the former Yugoslavia. Belgrade, the capital, sits at the confluence of the Sava and Danube rivers and has been an important regional hub for thousands of years — it has been destroyed and rebuilt more than 40 times in its history. Serbia is known for its vibrant music scene, including the Exit Festival, and a rich Eastern Orthodox Christian heritage with important medieval monasteries.",
  SK: "Slovakia is a landlocked Central European country sharing borders with Austria, Czech Republic, Hungary, Poland, and Ukraine. It was joined with the Czech Republic in Czechoslovakia until the two nations amicably separated in 1993 in the Velvet Divorce. Bratislava, the capital, is uniquely positioned so that residents can reach three different countries — Slovakia, Austria, and Hungary — within an hour's drive, making it one of Europe's most internationally connected capitals.",
  SI: "Slovenia is one of the smallest and most prosperous countries in Central Europe, known for its alpine terrain, pristine lakes, medieval old towns, and remarkable biodiversity packed into a small area. It was the first former Yugoslav republic to join the European Union in 2004. Lake Bled, with its island church and clifftop castle reflected in turquoise glacial waters, is one of Europe's most photographed and widely recognised landscapes.",
  ES: "Spain is the second-largest country in the European Union by area, situated on the Iberian Peninsula with additional territory in the Canary Islands, Balearic Islands, and two cities on the North African coast. It has a rich cultural heritage blending Roman, Moorish, and Christian traditions, visible in its architecture, art, cuisine, and festivals. Spain has more UNESCO World Heritage Sites than almost any other country and is one of the world's most visited nations.",
  SE: "Sweden is the largest country in Northern Europe and is known for its progressive social model, high standard of living, and a long tradition of neutrality in international conflicts. It is home to the Nobel Prize, awarded annually in Stockholm, and has produced globally influential exports including IKEA, Spotify, Volvo, ABBA, and a remarkable tradition of children's literature. Sweden joined the European Union in 1995 and has one of the world's highest rates of gender equality.",
  CH: "Switzerland is a landlocked country in Central Europe famous for its stunning alpine scenery, precision watchmaking, chocolate, cheese, and centuries of political neutrality. The Swiss Confederation, founded in 1291, is one of the world's oldest federations and has maintained armed neutrality in European conflicts since 1815. Switzerland is home to the International Red Cross (founded there in 1863), numerous United Nations agencies, and has four official national languages: German, French, Italian, and Romansh.",
  UA: "Ukraine is the largest country situated entirely within Europe, a vast nation with a rich agricultural tradition — it was once called the 'breadbasket of Europe' — and significant mineral and industrial resources. Kyiv, one of Eastern Europe's oldest and most historic cities, was the capital of the medieval Kyivan Rus state, a major cultural and political centre of early medieval Europe. Ukraine declared independence from the Soviet Union in 1991 and has a population of around 40 million people.",
  GB: "The United Kingdom consists of four constituent nations — England, Scotland, Wales, and Northern Ireland — and was historically the centre of the world's largest empire, covering approximately a quarter of Earth's land surface at its peak. London, the capital, is one of the world's leading financial, cultural, and political cities, home to institutions from the British Museum to the Houses of Parliament. The UK is a founding member of NATO and a permanent member of the UN Security Council.",
  VA: "Vatican City is the world's smallest internationally recognised country, an independent city-state entirely within Rome covering just 44 hectares. It serves as the headquarters of the Roman Catholic Church and the residence of the Pope, giving this tiny territory immense religious significance for over 1.3 billion Catholics worldwide. Vatican City is home to St Peter's Basilica, the Sistine Chapel with Michelangelo's famous ceiling fresco, and some of the world's most important art and historical collections.",

  // ── AFRICA ──────────────────────────────────────────────────────────────────
  DZ: "Algeria is the largest country in Africa and in the Arab world by area, located in North Africa with a Mediterranean coastline in the north and the Sahara Desert covering about 90% of its territory. The country gained independence from France in 1962 after a long and costly eight-year independence war. Algeria has significant oil and natural gas reserves, and its capital Algiers — known as 'Alger la Blanche' (Algiers the White) — is one of North Africa's most striking cities.",
  AO: "Angola is a large country on the southwestern coast of Africa, rich in oil, diamonds, and other natural resources. It was a Portuguese colony for nearly 500 years before gaining independence in 1975, which was immediately followed by a devastating civil war that lasted until 2002. Luanda, the capital, grew rapidly into one of Africa's most expensive cities due to the oil boom, though the country's wealth remains very unevenly distributed.",
  BJ: "Benin is a small West African nation historically home to the powerful Kingdom of Dahomey, known for its sophisticated military, its all-female royal regiment called the Agojie, and its significant role in the Atlantic slave trade. The country is considered the birthplace of Vodun (Voodoo) religion, which spread to Haiti and other parts of the Americas through the slave trade. Benin was renamed from the Republic of Dahomey in 1975.",
  BW: "Botswana is a landlocked country in Southern Africa that has undergone one of history's most remarkable development transformations, going from one of Africa's poorest nations at independence in 1966 to a middle-income country driven by diamond mining and stable governance. It is home to the Okavango Delta, one of the world's largest inland deltas, which floods seasonally to create an extraordinary wildlife-rich oasis in the Kalahari Desert. Botswana has maintained democratic governance since independence.",
  BF: "Burkina Faso is a landlocked West African country with a rich tradition of art, music, and film despite being one of the world's least economically developed nations. It was formerly known as Upper Volta before being renamed in 1984 to mean 'Land of Incorruptible People' in two local languages. The country hosts FESPACO, one of Africa's most prestigious film and television festivals, held every two years in the capital Ouagadougou.",
  BI: "Burundi is one of the world's smallest and most densely populated countries, a landlocked nation in the Great Rift Valley of Central Africa. It shares significant ethnic, linguistic, and cultural ties with Rwanda to the north. Despite having fertile agricultural land and a beautiful landscape of hills and lakes overlooking Lake Tanganyika, Burundi is consistently ranked among the world's least developed nations.",
  CM: "Cameroon is located at the junction of West and Central Africa and is often called 'Africa in miniature' for its extraordinary geographical and cultural diversity, encompassing Atlantic beaches, volcanic mountains, savanna grasslands, tropical rainforests, and the Saharan fringes. The country has over 250 ethnic groups and was formerly divided between British and French colonial administration. Yaoundé is the political capital while Douala is the main port city and economic hub.",
  CV: "Cape Verde is an archipelago of ten volcanic islands in the central Atlantic Ocean, located about 570 kilometres off the coast of West Africa. The islands had no indigenous population and were uninhabited until Portuguese colonisation in the 15th century. Cape Verde is known internationally for its distinctive morna music, associated with the legendary singer Cesária Évora, and has developed a stable democratic government and relatively strong economy for a small island nation.",
  CF: "The Central African Republic is a landlocked country in Central Africa, one of the world's least developed and most sparsely populated nations despite having significant timber, diamond, gold, and uranium resources. Bangui, the capital, sits on the Ubangi River which forms the border with the Democratic Republic of the Congo. The country has experienced persistent political instability and armed conflict since independence from France in 1960.",
  TD: "Chad is the fifth-largest country in Africa, a vast landlocked nation spanning from the Sahara Desert in the north — where the Tibesti Mountains contain dramatic desert landscapes — to tropical savannas and wetlands in the south. Lake Chad, which gives the country its name, was once one of Africa's largest lakes but has shrunk dramatically in recent decades due to climate change and agricultural water use. Chad is among the world's most remote and least developed countries.",
  KM: "Comoros is a small archipelago nation in the Indian Ocean between northern Madagascar and the coast of Mozambique, consisting of three main volcanic islands. It is one of the world's smallest and least developed nations and has experienced remarkable political instability since gaining independence from France in 1975. The Comoros islands are a major global producer of ylang-ylang, an essential oil widely used in the fragrance and cosmetics industry.",
  CG: "The Republic of the Congo, sometimes called Congo-Brazzaville, is a Central African country along the Congo River, distinct from the much larger Democratic Republic of the Congo across the water. It gained independence from France in 1960 and has significant offshore oil reserves. Its capital Brazzaville sits directly across the Congo River from Kinshasa, making them the world's closest pair of capital cities, visible to each other across the water.",
  CD: "The Democratic Republic of the Congo is the second-largest country in Africa and home to the Congo Rainforest, the world's second-largest tropical rainforest, sometimes called the 'lungs of Africa.' The country has extraordinary mineral wealth, including the majority of the world's cobalt reserves along with significant coltan, diamonds, and gold, though this has been a persistent source of conflict. Kinshasa is one of the most populous cities in Africa.",
  CI: "Côte d'Ivoire (Ivory Coast) is the world's largest producer of cocoa beans, supplying roughly a third of the global supply, and is a major economic hub in West Africa. It has two capitals: Yamoussoukro, the official political capital home to the enormous Basilica of Our Lady of Peace, and Abidjan, the economic and commercial centre. The country has a diverse cultural heritage and significant mineral resources.",
  DJ: "Djibouti is a tiny nation at the Horn of Africa where the Red Sea meets the Gulf of Aden, occupying one of the world's most strategically important maritime chokepoints. This location has made it home to multiple foreign military bases — American, French, Chinese, Japanese, and Italian — a unique concentration for such a small country. Despite limited natural resources, Djibouti generates significant revenue from port services and serves as the main trade gateway for landlocked Ethiopia.",
  EG: "Egypt is a transcontinental country spanning northeastern Africa and the Sinai Peninsula of Asia, home to one of the world's oldest and most influential civilisations, which flourished for over 3,000 years along the Nile River. The country is home to iconic ancient monuments including the Pyramids of Giza, the only surviving wonder of the ancient world, and the Sphinx. Egypt controls the Suez Canal, one of the world's most strategically vital shipping routes, connecting the Mediterranean and Red Seas.",
  GQ: "Equatorial Guinea is the only Spanish-speaking country in Africa, a distinction reflecting its colonial history as a Spanish territory. It consists of a mainland region called Río Muni and several islands including Bioko, where the capital Malabo is located. The discovery of significant offshore oil deposits in the 1990s dramatically increased national income, though wealth distribution remains highly unequal among the population.",
  ER: "Eritrea is a small nation on the Horn of Africa with a long Red Sea coastline, bordering Sudan, Ethiopia, and Djibouti. It gained independence from Ethiopia in 1993 following a 30-year independence war. The country has nine officially recognised ethnic groups and maintains a mandatory national service programme. Its port city of Massawa and capital Asmara feature distinctive Italian colonial architecture, and Asmara's modernist buildings are a UNESCO World Heritage Site.",
  SZ: "Eswatini (formerly Swaziland, renamed in 2018) is a small landlocked kingdom in Southern Africa almost entirely surrounded by South Africa. It is one of the world's last remaining absolute monarchies, ruled by King Mswati III. The country is known for its colourful cultural traditions, including the annual Umhlanga (Reed Dance) ceremony and the Incwala first fruits festival.",
  ET: "Ethiopia is the oldest independent country in Africa and one of the world's oldest nations, having successfully resisted European colonisation by defeating Italy at the Battle of Adwa in 1896. It is the second most populous country in Africa and the most populous landlocked country in the world. Ethiopia is widely considered the birthplace of coffee and is home to some of humanity's earliest known fossil remains, including the famous 'Lucy' skeleton discovered in 1974.",
  GA: "Gabon is a Central African country on the Atlantic coast known for its exceptional tropical rainforest, which covers more than 85% of its territory and is home to forest elephants, gorillas, chimpanzees, and the world's largest population of mandrills. The country has significant offshore oil reserves and manganese deposits, making it one of the more prosperous nations in sub-Saharan Africa. Gabon has committed to protecting large portions of its territory in national parks.",
  GM: "Gambia is the smallest country on mainland Africa, a narrow strip of land averaging just 50 kilometres wide that runs 300 kilometres along the Gambia River, almost entirely surrounded by Senegal. The Gambia River region was a significant area for the Atlantic slave trade. Today the country is known for its abundant birdlife, attracting birdwatchers from across Europe, and the Kunta Kinteh Island, a UNESCO World Heritage Site connected to the history of slavery.",
  GH: "Ghana was the first sub-Saharan African country to gain independence from colonial rule, achieving it in 1957 under Kwame Nkrumah, inspiring independence movements across the continent. Known during the colonial era as the Gold Coast, the country chose the name Ghana after the ancient Ghana Empire. Ghana has developed into one of West Africa's most stable democracies and is a significant producer of gold, cocoa, and increasingly, oil.",
  GN: "Guinea is a West African nation on the Atlantic coast, sometimes called Guinea-Conakry to distinguish it from Guinea-Bissau and Equatorial Guinea. It is one of the world's largest producers of bauxite, the ore from which aluminium is refined, and has significant iron ore, gold, and diamond deposits. Despite this mineral wealth, Guinea is one of the world's least developed countries, with most of its population depending on agriculture.",
  GW: "Guinea-Bissau is a small West African nation bordering Senegal and Guinea and is one of the world's least developed countries. The country includes the Bijagós Archipelago, a UNESCO biosphere reserve of extraordinary ecological richness, home to saltwater hippopotamuses and rare marine turtles. Guinea-Bissau gained independence from Portugal in 1974 and has experienced significant political instability since.",
  KE: "Kenya is a country in East Africa straddling the equator, renowned worldwide for the Maasai Mara ecosystem and the spectacular annual Great Migration of wildebeest and zebra. Nairobi, the capital, is East Africa's largest city and a major hub for international organisations and multinational companies. Kenya has long dominated international long-distance running, producing world record-holders and Olympic champions across distances from the 800 metres to the marathon.",
  LS: "Lesotho is a completely landlocked country entirely surrounded by South Africa, one of only three countries in the world with this geography. Known as the 'Kingdom in the Sky,' it is the only country in the world whose entire territory lies above 1,000 metres in elevation, giving it cool temperatures and spectacular mountain scenery. The Basotho people are known for their distinctive woven blankets and conical grass hats called mokorotlo.",
  LR: "Liberia is Africa's oldest republic, founded in 1847 by free Black Americans and formerly enslaved people who returned from the United States with the support of the American Colonization Society. This unusual history means Liberia's capital Monrovia is named after US President James Monroe, and the country's flag closely resembles the American flag. Liberia experienced devastating civil wars from 1989 to 2003 but has since made significant progress in rebuilding its institutions.",
  LY: "Libya is the fourth-largest country in Africa, situated in North Africa on the Mediterranean coast between Egypt and Tunisia. It has the continent's largest proven oil reserves, discovered in 1959, which transformed the country's economy. Libya was an Italian colonial territory from 1911 and gained independence in 1951. The ancient Roman cities of Leptis Magna and Sabratha on its Mediterranean coast are UNESCO World Heritage Sites of extraordinary grandeur.",
  MG: "Madagascar is the world's fourth-largest island, located in the Indian Ocean off the southeastern coast of Africa. It is one of the world's most important biodiversity hotspots, with over 90% of its wildlife found nowhere else on Earth — including all of its lemur species, most of the world's chameleon species, and iconic baobab trees. Madagascar separated from the Indian subcontinent approximately 88 million years ago and was first settled by seafarers from Borneo around 2,000 years ago.",
  MW: "Malawi is a small landlocked country in southeastern Africa known as the 'Warm Heart of Africa' for the warmth and friendliness of its people. Lake Malawi, one of Africa's Great Rift Valley lakes, occupies roughly a third of the country's area and contains more species of fish than any other lake on Earth. Despite this ecological richness, Malawi is one of the world's least developed nations with most of the population living in rural areas.",
  ML: "Mali is a large landlocked country in West Africa, much of which is covered by the Sahara Desert. It was home to three successive powerful empires — the Ghana, Mali, and Songhai Empires — which were major centres of trans-Saharan trade and Islamic scholarship from the 8th to the 16th centuries. Timbuktu, once one of the world's great centres of Islamic learning, is a UNESCO World Heritage Site in northern Mali.",
  MR: "Mauritania is a large country in northwestern Africa, serving as a cultural and geographical bridge between the Arab Maghreb of North Africa and sub-Saharan West Africa. The Sahara Desert covers most of its territory, with most of the population concentrated in the south. Mauritania was the last country in the world to officially abolish slavery, doing so in 1981, though enforcement continues to be a challenge.",
  MU: "Mauritius is a small island nation in the Indian Ocean, lying about 2,000 kilometres off the southeastern coast of Africa, with no indigenous human population before Portuguese sailors arrived in 1507. Mauritius was the only known habitat of the dodo, the large flightless bird that became extinct in the late 17th century after human arrival. Today it is known for its diverse culture, pristine beaches, and has developed into one of Africa's higher-income economies through tourism and financial services.",
  MA: "Morocco is a country in northwestern Africa at the crossroads of the Arab, Berber, and Mediterranean worlds, separated from Spain by only 14 kilometres at the Strait of Gibraltar. It is home to four UNESCO-listed imperial cities — Fes, Marrakech, Meknès, and Rabat — each with a historic old city of extraordinary character. Morocco's Atlas Mountains, Sahara Desert, Atlantic and Mediterranean coasts make it one of Africa's most geographically and culturally diverse countries.",
  MZ: "Mozambique is a country in southeastern Africa with a long Indian Ocean coastline of 2,470 kilometres. It gained independence from Portugal in 1975 after a decade-long independence war, followed by a civil war lasting until 1992. Mozambique has significant natural gas reserves off its northern coast, attracting major international energy investment, and is known for its vibrant music, cuisine, and the historic island of Mozambique, a UNESCO World Heritage Site.",
  NA: "Namibia is a southern African country known for the Namib Desert — one of the world's oldest deserts, having been arid for at least 55 million years — from which the country takes its name. It is one of Africa's most sparsely populated countries despite being larger than France. Namibia has spectacular wildlife experiences including the desert-adapted elephants and lions of Damaraland and the vast seal colonies of Cape Cross.",
  NE: "Niger is the largest country in West Africa by area, though the vast majority of its territory is covered by the Sahara Desert, with most of the population concentrated in a narrow fertile zone along its southern border. Named after the Niger River that passes through its southwestern corner, the country has significant uranium deposits making it one of the world's top uranium producers. Niger consistently ranks near the very bottom of global human development indices.",
  NG: "Nigeria is Africa's most populous country, home to over 200 million people and more than 500 distinct languages and ethnic groups, making it one of the world's most diverse nations. It is Africa's largest economy and a significant oil exporter, with a vibrant creative culture including Nollywood (the world's second-largest film industry by volume) and Afrobeats music that has gained enormous global influence. Nigeria's celebrated writers include Chinua Achebe and Nobel Prize laureate Wole Soyinka.",
  RW: "Rwanda is a small, densely populated landlocked country in Central Africa that has undergone an extraordinary transformation following the 1994 genocide, in which approximately 800,000 people were killed in 100 days — one of history's swiftest mass atrocities. In the decades since, Rwanda has achieved remarkable political stability, rapid economic growth, and progressive environmental policies. Kigali, the capital, is consistently rated one of Africa's cleanest, safest, and most organised cities.",
  ST: "São Tomé and Príncipe is a small island nation in the Gulf of Guinea and was uninhabited until Portuguese settlement in the 15th century made it one of Africa's first colonial outposts. The islands became a major sugar-producing centre using enslaved labour and were a crucial node in the Atlantic slave trade. Today São Tomé and Príncipe is known for its rich biodiversity, its peaceful transition to multiparty democracy in 1990, and the production of high-quality fine-flavour cacao.",
  SN: "Senegal is located on the westernmost tip of the African mainland and is one of West Africa's most stable and long-standing democracies. Known as the 'Gateway to Africa,' its capital Dakar was historically the administrative capital of French West Africa. Senegal's culture is celebrated for its traditional wrestling, its rich griot oral historian tradition, and internationally renowned artists like Youssou N'Dour.",
  SL: "Sierra Leone is a West African country with a history deeply intertwined with the transatlantic slave trade. Freetown, the capital, was founded in 1787 as a settlement for freed slaves from Britain, the Americas, and Nova Scotia, and its name reflects that founding purpose. The country has extraordinary natural resources including diamonds, titanium, and bauxite, and was severely affected by a civil war from 1991 to 2002.",
  SO: "Somalia occupies the Horn of Africa and has the longest coastline in mainland Africa, stretching nearly 3,300 kilometres. Despite having a common language, culture, and religion shared across its population — unusual in a region of great ethnic diversity — Somalia has lacked a functioning central government since 1991 and has experienced prolonged clan-based conflict. Somali culture has a rich tradition of poetry, and the country is sometimes called a 'nation of poets.'",
  ZA: "South Africa is the southernmost country in Africa and one of the continent's most economically developed and culturally diverse nations. The country peacefully ended its apartheid system of racial segregation in 1994, holding its first fully democratic elections that year and electing Nelson Mandela as president. South Africa has extraordinary natural diversity spanning the Cape Floristic Region, Kruger National Park, and the Drakensberg Mountains, and is the only country to have voluntarily dismantled its nuclear weapons programme.",
  SS: "South Sudan is the world's newest internationally recognised country, gaining independence from Sudan in July 2011 following a 2005 peace agreement and a referendum in which 98.83% voted for independence. Despite significant oil reserves, it is one of the world's least developed nations and was quickly embroiled in a devastating civil war starting in 2013. Juba, the capital, sits on the Nile River and is a rapidly growing frontier city.",
  SD: "Sudan is the third-largest country in Africa and was the continent's largest until South Sudan seceded in 2011. Located in northeastern Africa, Sudan is home to more ancient pyramids than Egypt — the Nubian kingdoms at Meroe, Nuri, and El-Kurru have hundreds of smaller, steeper pyramids scattered across the desert. Sudan gained independence from British-Egyptian rule in 1956 and the Nile flows through the country from south to north.",
  TZ: "Tanzania is East Africa's largest country and home to some of the continent's most iconic landscapes and wildlife. Mount Kilimanjaro, Africa's highest peak, the Serengeti's annual wildebeest migration, and the Ngorongoro Crater are all within its borders. The semi-autonomous archipelago of Zanzibar, once a powerful independent sultanate and centre of the Indian Ocean spice trade, merged with mainland Tanganyika to form Tanzania in 1964.",
  TG: "Togo is one of Africa's narrowest nations, stretching from the Gulf of Guinea in the south to Burkina Faso in the north. It was a German protectorate before being divided between France and Britain after World War I, with the French portion becoming independent Togo in 1960. Lomé, the capital, sits on the Atlantic coast and is known as one of West Africa's more pleasant and accessible cities.",
  TN: "Tunisia is the northernmost country in Africa, where the continent reaches closest to Europe with just 140 kilometres separating it from the Italian island of Sicily. The ancient Carthaginian civilisation, a rival of Rome, was centred near modern-day Tunis. Tunisia was the birthplace of the Arab Spring in late 2010, when protests sparked a wave of revolutionary movements that spread across the Arab world.",
  UG: "Uganda is a landlocked East African country known as the 'Pearl of Africa' for its extraordinary natural beauty and biodiversity. The country is home to approximately half of the world's remaining mountain gorillas, and the source of the Nile River is at the northern end of Lake Victoria within Uganda. Kampala, the capital, is a rapidly growing city built across multiple hills and is one of East Africa's most dynamic urban centres.",
  ZM: "Zambia is a landlocked country in southern Africa, formerly known as Northern Rhodesia, which gained independence from Britain in 1964. It is named after the Zambezi River, one of Africa's great rivers and the site of Victoria Falls on the Zambia-Zimbabwe border — one of the world's most spectacular waterfalls. Zambia is a significant copper producer, and the Copperbelt region in the north was historically one of the world's richest copper deposits.",
  ZW: "Zimbabwe is a landlocked country in southern Africa home to the ruins of Great Zimbabwe, a medieval stone city that at its peak housed up to 18,000 people and gave the country its name. Victoria Falls, shared with Zambia and one of the Seven Natural Wonders of the World, lies on its northwestern border. Once the 'breadbasket of Africa' for its agricultural productivity, Zimbabwe experienced severe economic difficulties in the 2000s and has been in a period of recovery since.",

  // ── ASIA ────────────────────────────────────────────────────────────────────
  AF: "Afghanistan is a landlocked country at the crossroads of Central and South Asia, bordered by Pakistan, Iran, Turkmenistan, Uzbekistan, Tajikistan, and China. It has been at the centre of geopolitical competition for centuries, often described as the 'Graveyard of Empires' for the many foreign powers who have attempted to subdue it. Afghanistan has extraordinary untapped mineral deposits including the world's largest known lithium reserves along with significant iron, copper, gold, and rare earth minerals.",
  AM: "Armenia is a small landlocked country in the South Caucasus with one of the world's oldest continuous civilisations, and was the first country in the world to adopt Christianity as its state religion, in 301 AD. The country is home to some of the world's earliest Christian churches and monasteries, including Etchmiadzin Cathedral, and has a 6,000-year winemaking tradition evidenced by archaeological finds. Armenia has a deep cultural identity shaped significantly by the Armenian Genocide of 1915.",
  AZ: "Azerbaijan is a South Caucasian country bordering the Caspian Sea, Georgia, Russia, Iran, and Armenia, and is one of the oldest oil-producing regions in the world, with records of oil collection dating to the 10th century. Baku, the capital, is known for its striking contrast of medieval walls and winding old city lanes alongside futuristic modern architecture including the flame-shaped Flame Towers. The country is also home to Yanar Dag ('Burning Mountain'), a natural gas seep that has burned continuously for centuries.",
  BD: "Bangladesh is a South Asian country almost entirely surrounded by India, with a small border with Myanmar, and is one of the world's most densely populated countries, with around 170 million people in an area smaller than Greece. It achieved independence from Pakistan in 1971 following a liberation war. Bangladesh is the world's second-largest garment exporter and has made remarkable progress in poverty reduction, women's education, and reducing child mortality.",
  BT: "Bhutan is a small Himalayan Buddhist kingdom between India and China, known for its unique philosophy of measuring national progress through 'Gross National Happiness' rather than purely economic indicators. It was the last country in the world to introduce television and the internet, doing so in 1999 and 2000 respectively. Bhutan is entirely carbon negative, absorbing far more carbon dioxide than it produces due to its vast protected forests, and conservation is central to national policy.",
  BN: "Brunei is a small, wealthy sultanate on the island of Borneo in Southeast Asia, entirely surrounded by Malaysia except for its South China Sea coastline. It has one of the highest per-capita incomes in the world due to its substantial oil and natural gas reserves, and is governed by Sultan Hassanal Bolkiah, one of the world's longest-reigning monarchs. Brunei maintains Islamic law alongside civil law and is one of the few remaining absolute monarchies.",
  KH: "Cambodia is a Southeast Asian country home to Angkor Wat, the world's largest religious monument, a 12th-century Hindu temple complex later converted to Buddhism. The country suffered the devastating Khmer Rouge genocide from 1975 to 1979, during which an estimated 1.7 to 2.5 million people — roughly a quarter of the population — died from execution, starvation, disease, and forced labour. Cambodia has since rebuilt significantly and attracts millions of tourists to the magnificent temples of Angkor.",
  CN: "China is the world's most populous country and has the world's second-largest economy, home to one of history's longest continuous civilisations spanning over 5,000 years. The Great Wall, the Terracotta Army, the Forbidden City, and the Li River karst landscape are among its most iconic landmarks. China's 'Four Great Inventions' — paper, printing, gunpowder, and the compass — transformed human civilisation worldwide, and the country has been a centre of philosophical, scientific, and artistic achievement throughout recorded history.",
  GE: "Georgia is a country at the crossroads of Eastern Europe and Western Asia in the South Caucasus, bordered by Russia, Turkey, Armenia, and Azerbaijan. It is one of the world's oldest winemaking regions, with an 8,000-year tradition of fermenting wine in clay vessels called qvevri buried underground. Georgia adopted Christianity as its state religion in the 4th century AD and has one of the world's oldest and most distinctive alphabets, the Georgian script, dating to at least the 5th century.",
  IN: "India is the world's most populous country, home to one of history's oldest civilisations and extraordinary diversity in language, religion, culture, and geography — it has 22 officially recognised languages and hundreds more spoken across the subcontinent. It is the birthplace of four major world religions: Hinduism, Buddhism, Jainism, and Sikhism. India has the world's largest film industry by number of productions and has made fundamental contributions to mathematics, astronomy, medicine, and philosophy throughout history.",
  ID: "Indonesia is the world's largest archipelago nation, consisting of more than 17,000 islands and home to the world's fourth-largest population. It spans a vast area straddling the equator in Southeast Asia and has extraordinary biodiversity including orangutans, Komodo dragons, Sumatran tigers, and pygmy elephants. Indonesia has the world's largest Muslim population while maintaining a pluralistic, secular constitution, and is home to a remarkable diversity of more than 700 languages.",
  JP: "Japan is an island nation in the Pacific Ocean comprising four main islands plus more than 6,800 smaller ones, home to a society that uniquely blends ancient traditions with cutting-edge modernity. The Japanese imperial dynasty traces an unbroken lineage for over 2,600 years, making it the world's oldest hereditary monarchy. Japan is famous for its cherry blossom festivals, tea ceremony, manga and anime, sushi, precision engineering, and has made profound contributions to global culture, design, and technology.",
  KZ: "Kazakhstan is the world's largest landlocked country, a vast Central Asian nation spanning parts of both Europe and Asia, larger than Western Europe combined. It was the last Soviet republic to declare independence in 1991 and has significant oil, natural gas, and mineral deposits that have driven rapid economic development. Astana, the purpose-built capital relocated in 1997, features striking futuristic architecture rising from the Kazakh steppe.",
  KG: "Kyrgyzstan is a small, mountainous Central Asian country where more than 90% of the territory lies above 1,500 metres in elevation. It is known for its spectacular alpine scenery, nomadic heritage, and one of the world's longest epic poems — the Manas — which runs to approximately 500,000 lines and is still recited by professional storytellers. Kyrgyzstan hosts the World Nomad Games, a biennial celebration of traditional nomadic sports and culture from across Central Asia.",
  LA: "Laos is the only landlocked country in Southeast Asia and one of the world's few remaining single-party communist states. During the Vietnam War era, Laos was the most heavily bombed country per capita in history, with over 2 million tonnes of ordnance dropped between 1964 and 1973. Despite this history, modern Laos is known for its Buddhist temple culture, the Mekong River, and the charming UNESCO-listed ancient capital Luang Prabang.",
  MY: "Malaysia is a Southeast Asian country consisting of two distinct regions separated by the South China Sea — Peninsular Malaysia (bordering Thailand) and Malaysian Borneo. It is a multicultural melting pot of Malay, Chinese, Indian, and indigenous cultures, reflected in its extraordinarily diverse food, festivals, and languages. The Petronas Twin Towers in Kuala Lumpur were the world's tallest buildings from 1998 to 2004 and remain iconic symbols of Malaysia's rapid development.",
  MV: "The Maldives is an archipelago nation in the Indian Ocean south of India, consisting of 26 coral atolls and more than 1,000 individual coral islands. It is the world's lowest-lying country, with an average ground elevation of just 1.5 metres above sea level, making it acutely vulnerable to rising sea levels caused by climate change. The Maldives has developed a successful tourism economy centred on its legendary overwater bungalows, crystal-clear lagoons, and exceptional marine biodiversity.",
  MN: "Mongolia is a vast landlocked country in East Asia between Russia and China, and is the world's most sparsely populated sovereign state, with only about 3.3 million people spread across an area nearly four times the size of France. It was the centre of the Mongol Empire under Genghis Khan in the 13th century, the largest contiguous land empire in history. A significant portion of Mongolia's population still maintains a semi-nomadic lifestyle, living seasonally in traditional portable dwellings called gers.",
  MM: "Myanmar (also known as Burma) is a Southeast Asian country with remarkable ethnic and cultural diversity, home to more than 135 distinct ethnic groups. Its ancient city of Bagan contains over 2,000 Buddhist temples, pagodas, and monasteries spread across 40 square kilometres, one of Asia's most extraordinary archaeological landscapes. Myanmar has a deeply complex modern political history and is navigating significant internal challenges.",
  NP: "Nepal is a small Himalayan country between India and China, home to eight of the world's ten highest mountain peaks, including Mount Everest at 8,849 metres. It is the birthplace of Siddhartha Gautama, the historical Buddha, born in Lumbini around 563 BCE. Despite being one of Asia's poorest nations, Nepal attracts hundreds of thousands of trekkers and mountaineers every year drawn by its extraordinary Himalayan landscapes and spiritual heritage.",
  KP: "North Korea (the Democratic People's Republic of Korea) occupies the northern half of the Korean Peninsula and operates as one of the world's most isolated and secretive states, governed by a single family dynasty — the Kim family — since its founding. The country declared itself a nuclear weapons state in 2005 and maintains one of the world's largest standing armies. Despite its isolation, North Korea has ancient Buddhist temples, the Paektu Mountain crater lake, and a highly developed domestic cultural tradition.",
  PK: "Pakistan is a South Asian country created from British India in 1947 as a homeland for South Asian Muslims during Partition. It is the world's second-most populous Muslim-majority country and has a complex ethnic tapestry including Punjabis, Pashtuns, Sindhis, and Baloch peoples. Pakistan is home to K2 (the world's second-highest mountain), the ancient Indus Valley city of Mohenjo-daro, and some of the most spectacular mountain scenery on Earth in the Karakoram and Hindu Kush ranges.",
  PH: "The Philippines is a Southeast Asian archipelago of more than 7,100 islands, named after King Philip II of Spain, reflecting more than 300 years of Spanish colonial rule that ended in 1898. It is the world's third-largest English-speaking country and has a culture uniquely blending indigenous, Malay, Spanish, and American influences. The Philippines has extraordinary marine biodiversity, with Palawan and the Tubbataha Reef sitting within the Coral Triangle, the global centre of marine biodiversity.",
  SG: "Singapore is a city-state and island nation at the southern tip of the Malay Peninsula, one of the world's most prosperous countries and a major global hub for finance, trade, aviation, and logistics. Despite having no natural resources, Singapore has built a remarkable economy through strategic port management, manufacturing, and financial services. It is the world's most densely populated country after Monaco, with a population of around 5.8 million in just 733 square kilometres.",
  LK: "Sri Lanka is a teardrop-shaped island nation in the Indian Ocean off the southern tip of India, known as the 'Pearl of the Indian Ocean.' It has one of the oldest documented histories in Asia, with a continuous chronicle of rulers dating to the 6th century BCE. Sri Lanka is the world's leading exporter of Ceylon tea and has a rich Buddhist heritage with ancient cities such as Anuradhapura and Polonnaruwa, both UNESCO World Heritage Sites.",
  KR: "South Korea occupies the southern portion of the Korean Peninsula and has achieved one of the most dramatic economic transformations in history, going from one of the world's poorest nations after the 1950-53 Korean War to a high-income, technologically advanced society in a single generation. It is home to globally recognised companies including Samsung, LG, Hyundai, and Kia. South Korean pop culture — K-pop, K-drama, and films such as the Oscar-winning Parasite — has achieved extraordinary global reach.",
  TJ: "Tajikistan is the smallest country in Central Asia by area yet has the highest proportion of mountainous territory, with more than 93% covered by mountains including the Pamir range — often called the 'Roof of the World.' It is the poorest of the former Soviet Central Asian republics. Tajikistan is the only Persian-speaking country in Central Asia and has heritage closely tied to ancient Persian civilisation; the Sogdian people, ancestors of modern Tajiks, played a major role on the Silk Road.",
  TH: "Thailand is a Southeast Asian country known as the 'Land of Smiles' and is the only country in mainland Southeast Asia never to have been colonised by a European power. Bangkok, the capital, is one of the world's most visited cities, known for its ornate temples, vibrant street food culture, and famous floating markets. Thailand is a constitutional monarchy where the king holds deep cultural reverence, and has a strong Theravada Buddhist tradition.",
  TL: "Timor-Leste (East Timor) is one of the world's newest countries, gaining independence in 2002 after 24 years of Indonesian occupation following Portugal's withdrawal from its former colony. Located on the eastern half of the island of Timor in Southeast Asia, it is one of only two predominantly Roman Catholic nations in Asia. Timor-Leste has significant offshore oil and gas reserves and is home to remarkable coral reef systems in the Coral Triangle.",
  TM: "Turkmenistan is a Central Asian country bordered by Kazakhstan, Uzbekistan, Afghanistan, Iran, and the Caspian Sea, and is one of the world's most isolated and authoritarian states. It holds the world's fourth-largest natural gas reserves and uses this wealth to provide heavily subsidised utilities and fuel to citizens. The country is home to the Darvaza gas crater — a natural gas field that was set alight in 1971 and continues to burn today, nicknamed the 'Door to Hell.'",
  UZ: "Uzbekistan is a double-landlocked Central Asian country that was the heartland of the ancient Silk Road, the trade network connecting China to the Mediterranean world. Cities like Samarkand and Bukhara were among the medieval world's greatest centres of Islamic scholarship, architecture, and commerce, with breathtaking tilework that rivals anything on Earth. Uzbekistan is also the birthplace of medieval mathematician al-Khwarizmi, from whose name the word 'algorithm' is ultimately derived.",
  VN: "Vietnam is a Southeast Asian country stretching 1,650 kilometres along the eastern Indochinese Peninsula with an extraordinarily long and varied coastline. Despite centuries of Chinese rule, French colonisation, and a devastating war with American involvement that ended in 1975, Vietnam has maintained a strong and distinct cultural identity. Since the Doi Moi economic reforms of 1986, Vietnam has become one of Asia's fastest-growing economies, transforming from an agricultural society to a major manufacturing and export hub.",

  // ── MIDDLE EAST ─────────────────────────────────────────────────────────────
  BH: "Bahrain is a small island nation in the Persian Gulf and was the first country in the Gulf to discover and export oil, in 1932. It was the site of the ancient Dilmun civilisation, one of the ancient world's great trading centres, and has been a regional hub for commerce and pearl diving for thousands of years. Bahrain is considered the most socially liberal of the Gulf monarchies and has a cosmopolitan, diverse population.",
  IR: "Iran, historically known as Persia, is home to one of the world's oldest continuous civilisations with a history spanning more than 5,000 years, including some of antiquity's greatest empires such as the Achaemenid Empire under Cyrus the Great. It is the world's largest Shia Muslim-majority country and has 27 UNESCO World Heritage Sites including Persepolis, the ceremonial capital of the ancient Persian Empire. Iran holds the world's second-largest natural gas reserves and fourth-largest oil reserves.",
  IQ: "Iraq is located in the Fertile Crescent of western Asia, in the region of ancient Mesopotamia — the 'land between the rivers' of the Tigris and Euphrates — widely regarded as the birthplace of civilisation, where writing, codified law, agriculture, and the world's first cities all emerged. The ancient city of Babylon was one of the ancient world's most magnificent metropolises. Iraq holds the world's fifth-largest proven oil reserves and has extraordinary archaeological heritage including the ancient Sumerian city of Ur.",
  IL: "Israel is a small Middle Eastern country on the eastern shore of the Mediterranean Sea, established in 1948 as the world's only Jewish-majority state and the historical homeland of the Jewish people. Jerusalem, its proclaimed capital, is one of the world's oldest continuously inhabited cities and is sacred to Judaism, Christianity, and Islam. Israel has developed one of the world's most innovative technology sectors, often called 'Silicon Wadi,' with more startup companies per capita than almost any other nation.",
  JO: "Jordan is a small Arab kingdom in the heart of the Middle East, home to Petra — the ancient Nabataean city carved into rose-red sandstone cliffs — one of the world's most spectacular archaeological sites and one of the New Seven Wonders of the World. The Dead Sea on Jordan's western border is the lowest point on Earth's surface at 430 metres below sea level, and its hypersaline waters allow bathers to float effortlessly. Jordan has been a relatively stable centre in a volatile region and hosts millions of refugees.",
  KW: "Kuwait is a small emirate in the northwestern Persian Gulf with the world's sixth-largest proven oil reserves. It was occupied by Iraq in 1990 and liberated by a US-led coalition in the 1991 Gulf War, an event that shaped modern Middle Eastern geopolitics. Kuwait has used its oil wealth to develop generous social services for its citizens, including free healthcare, education, and no personal income tax.",
  LB: "Lebanon is a small country on the eastern Mediterranean coast with an extraordinarily diverse cultural heritage shaped by Phoenician, Greek, Roman, Arab, Crusader, Ottoman, and French influences. Once called the 'Switzerland of the Middle East' for its banking sector and cosmopolitan lifestyle, Beirut was a major regional cultural and commercial centre. Lebanon is home to the ancient cedars of Lebanon, celebrated in the Bible and depicted prominently on the national flag and coat of arms.",
  OM: "Oman is located on the southeastern corner of the Arabian Peninsula with coastlines on the Arabian Sea and Gulf of Oman, and is one of the oldest independent states in the Arab world with a seafaring and trading tradition stretching back 5,000 years. The Sultan of Oman has historically pursued a carefully balanced foreign policy, maintaining good relations across regional political divides. Oman is known for its beautiful wadis, ancient forts, and frankincense production from the southern Dhofar region.",
  PS: "Palestine refers to the Palestinian territories of the West Bank and the Gaza Strip, home to a population of around 5 million Palestinians. The region has deep historical and religious significance to Judaism, Christianity, and Islam — Jerusalem contains some of the most sacred sites for all three faiths. The Palestinian Authority, established following the 1993 Oslo Accords, exercises limited self-governance in parts of the West Bank.",
  QA: "Qatar is a small peninsula in the Persian Gulf with the world's highest per-capita income, driven by its enormous natural gas reserves — the world's third-largest. It is home to Al Jazeera, one of the world's most widely watched international news networks, launched in 1996. Qatar hosted the 2022 FIFA World Cup, becoming the first Arab and Muslim-majority country to host the tournament, a milestone of major cultural significance.",
  SA: "Saudi Arabia is the largest country in the Middle East and the birthplace of Islam, home to its two holiest cities — Mecca and Medina — which together receive around 15 million Muslim pilgrims annually for the Hajj and Umrah. The country holds the world's second-largest proven oil reserves and is the world's largest oil exporter, making it a central player in global energy markets. Saudi Arabia is governed as an absolute monarchy by the Al Saud royal family and is undergoing significant social and economic reform.",
  SY: "Syria is one of the oldest inhabited regions in the world, home to some of humanity's earliest permanent settlements, and Damascus is often cited as the world's oldest continuously inhabited city. The country has extraordinary historical heritage, including the ancient cities of Aleppo, Palmyra, and Bosra, all UNESCO World Heritage Sites. Syria experienced a devastating civil war beginning in 2011 that caused immense destruction to its people and to irreplaceable archaeological sites.",
  TR: "Turkey is a transcontinental country bridging Europe and Asia, with most of its territory on the Anatolian Peninsula. Istanbul, its largest city, was historically known as Constantinople and served as the imperial capital of both the Byzantine and Ottoman Empires for over a millennium. Turkey is home to extraordinary natural and archaeological wonders including Cappadocia's surreal rock formations, the ancient Greek city of Ephesus, and the Hagia Sophia.",
  AE: "The United Arab Emirates is a federation of seven emirates on the southeastern Arabian Peninsula that has transformed from a collection of small fishing and pearl-diving communities into one of the world's wealthiest nations in barely five decades, driven by oil revenues and economic diversification. Dubai is home to the Burj Khalifa, the world's tallest building, and has become a global hub for aviation, finance, tourism, and international business. Abu Dhabi, the capital emirate, holds the majority of the federation's oil wealth.",
  YE: "Yemen is located at the southern tip of the Arabian Peninsula where the Red Sea meets the Gulf of Aden, and is home to some of the Arabian Peninsula's oldest human settlements. The ancient city of Sana'a, the capital, features distinctive tower houses decorated with geometric plasterwork and is a UNESCO World Heritage Site. Yemen is one of the Arab world's poorest nations and the island of Socotra — part of Yemen — is sometimes called the 'Galápagos of the Indian Ocean' for its extraordinary endemic biodiversity.",

  // ── AMERICAS ────────────────────────────────────────────────────────────────
  AG: "Antigua and Barbuda is a twin-island Caribbean nation known for its 365 beaches — one for each day of the year — and for hosting Antigua Sailing Week, one of the world's most celebrated regattas. The island of Antigua was a major British Royal Navy base in the 18th century, with English Harbour preserving the historic dockyard where Admiral Horatio Nelson was stationed. The country gained independence from Britain in 1981.",
  AR: "Argentina is the second-largest country in South America, stretching from the subtropical north down to sub-Antarctic Patagonia and Cape Horn. Buenos Aires, the capital, is a cosmopolitan city strongly influenced by European immigration and known for its tango music and dance, vibrant cultural scene, and world-class restaurants. Argentina has won the FIFA World Cup three times and produced celebrated writers including Jorge Luis Borges.",
  BS: "The Bahamas is an archipelago of about 700 islands and 2,400 cays in the Atlantic Ocean north of Cuba, and is the site of Christopher Columbus's first landfall in the Americas on October 12, 1492. Today the Bahamas is one of the Caribbean's most prosperous nations, with tourism and offshore financial services as its main economic pillars. Its turquoise waters, coral reefs, and marine life make it a world-class scuba diving and sailing destination.",
  BB: "Barbados is the easternmost island in the Caribbean and is widely credited as the birthplace of rum — production from molasses began on Barbadian sugar plantations in the 17th century. The island was continuously under British rule from 1625 until independence in 1966, making it one of the most stable British colonial territories. In 2021, Barbados transitioned from a constitutional monarchy to a republic, with Rihanna — its most famous daughter — named a National Hero.",
  BZ: "Belize is the only English-speaking country in Central America and has extraordinary natural and cultural heritage. The Mesoamerican Barrier Reef, the second-longest coral reef in the world, runs along its entire Caribbean coastline. Belize also contains a remarkable concentration of ancient Maya sites scattered throughout its jungles, including the great city of Caracol, and gained independence from Britain (as British Honduras) in 1981.",
  BO: "Bolivia is a landlocked South American country with one of the world's highest and most isolated seats of government — La Paz, the administrative capital, sits at over 3,600 metres above sea level. The country has the world's largest salt flat, Salar de Uyuni (10,582 sq km), which becomes the world's largest natural mirror when flooded with a thin film of water. Bolivia also holds the world's largest known lithium reserves, a resource critical for electric vehicle batteries.",
  BR: "Brazil is the largest country in South America and the fifth-largest in the world, home to the Amazon Rainforest — the world's largest tropical rainforest — which contains roughly 10% of all species on Earth. Brazil has one of the world's most diverse populations, shaped by Indigenous, African, Portuguese, and subsequent immigrant heritage from around the world. It is renowned for its Carnival festival, passionate football culture, and the music genres of samba and bossa nova.",
  CA: "Canada is the second-largest country in the world by total area, spanning six time zones from the Atlantic to the Pacific to the Arctic Ocean. It is a bilingual nation with English and French as official languages, reflecting its complex colonial history and the distinct heritage of its Francophone population, particularly in Quebec. Canada is known for its vast and diverse natural landscapes, multicultural cities, and a universal healthcare system.",
  CL: "Chile is a long, narrow country stretching approximately 4,300 kilometres along South America's western coast, from the world's driest non-polar desert in the north to Patagonian glaciers and Cape Horn in the south. The Atacama Desert in northern Chile is so dry that in some areas no rainfall has ever been recorded. Easter Island (Rapa Nui), famous for its mysterious moai statues carved by the Rapa Nui people, is a Chilean Pacific territory.",
  CO: "Colombia is the only South American country with coastlines on both the Caribbean Sea and the Pacific Ocean, situated in the continent's northwestern corner. It is the world's top producer of emeralds, supplying around 90% of the global supply, and also produces significant coal, oil, and the world-famous Colombian coffee. Colombia has more bird species (over 1,900) than any other country on Earth, making it a premier destination for birdwatchers.",
  CR: "Costa Rica is a Central American country celebrated for its pioneering environmental policies and extraordinary biodiversity, protecting more than 25% of its territory in national parks, wildlife refuges, and biological reserves. It abolished its military in 1948 and has since channelled resources into education and healthcare. Costa Rica generates the vast majority of its electricity from renewable sources, primarily hydropower, wind, and geothermal energy from its chain of active volcanoes.",
  CU: "Cuba is the largest island in the Caribbean Sea, known internationally for its preserved classic American cars from the 1950s, hand-rolled cigars, rum, and vibrant music and dance traditions including salsa, son cubano, and mambo. The country has been governed by a communist government since the Cuban Revolution of 1959. Despite economic challenges, Cuba has an unusually high number of doctors per capita and has developed a significant pharmaceutical and medical biotechnology sector.",
  DM: "Dominica is known as the 'Nature Isle of the Caribbean' for its lush, volcanic landscape, hot springs, and some of the last well-preserved primary rainforest in the Eastern Caribbean. Not to be confused with the Dominican Republic, Dominica is home to the Kalinago people — the last pre-Columbian indigenous community in the Eastern Caribbean — who maintain their own territory on the island's eastern coast. The island has a growing eco-tourism industry.",
  DO: "The Dominican Republic shares the island of Hispaniola with Haiti and was the site of the first permanent European settlement in the Americas, established by Bartholomew Columbus in 1496. It is the most visited country in the Caribbean, with large resort areas along its northern and eastern coasts. Santo Domingo is home to the Cathedral of Santa María la Menor (1512), the oldest cathedral in the Americas.",
  EC: "Ecuador is a small country on South America's northwestern coast named after the equator that runs through its territory. It is considered one of the world's most biodiverse countries by land area, and the Galápagos Islands — an Ecuadorian archipelago 1,000 kilometres offshore — are where Charles Darwin developed key insights that led to his theory of natural selection. Ecuador was the first country to enshrine the legal rights of nature in its national constitution, in 2008.",
  SV: "El Salvador is the smallest and most densely populated country in Central America and the only one without a Caribbean coastline. It is known for its surf culture along the Pacific coast, the ancient Maya city of Joya de Cerén (preserved by volcanic ash and called the 'Pompeii of the Americas'), and its chain of active volcanoes. El Salvador became the first country in the world to adopt Bitcoin as legal tender in 2021.",
  GD: "Grenada, the 'Spice Isle,' is the world's second-largest producer of nutmeg and mace after Indonesia, along with cinnamon, cloves, and ginger. This small Caribbean island gained independence from Britain in 1974. St George's, the capital, with its horseshoe-shaped harbour ringed by colourful colonial buildings and overlooked by a French fort, is widely considered one of the most beautiful harbour towns in the Caribbean.",
  GT: "Guatemala is the most populous country in Central America and was the heartland of the ancient Maya civilisation, which built cities with sophisticated astronomical observatories and developed one of the few fully developed writing systems in the pre-Columbian Americas. The ancient Maya calendar, developed in Guatemala, attracted global attention in 2012. The colonial capital Antigua Guatemala is a UNESCO World Heritage Site.",
  GY: "Guyana is the only English-speaking country in South America, sharing borders with Venezuela, Brazil, and Suriname, and was formerly British Guiana before independence in 1966. More than 80% of its territory is covered by tropical rainforest, among the most intact in South America. The discovery of major offshore oil reserves in 2015 has made Guyana one of the world's fastest-growing economies.",
  HT: "Haiti occupies the western third of Hispaniola in the Caribbean and in 1804 became the first Black republic in the world and the first nation established through a successful slave revolt — the Haitian Revolution inspired abolitionists worldwide. Haiti has a rich culture deeply connected to West African traditions, with Haitian Creole spoken nationwide and Vodou practised alongside Roman Catholicism. Despite significant challenges, it has a vibrant artistic tradition including internationally recognised painting and sculpture.",
  HN: "Honduras is a Central American country with coastlines on the Caribbean Sea and the Pacific, home to Copán — one of the most important archaeological sites of the ancient Maya, known for its elaborately carved stelae and hieroglyphic stairway. The Bay Islands off the Caribbean coast are renowned for scuba diving due to their position on the Mesoamerican Barrier Reef. Honduras is one of Central America's most biodiverse countries.",
  JM: "Jamaica is a small Caribbean island that has had a cultural influence on the world far exceeding its size. It is the birthplace of reggae music, popularised globally by Bob Marley, and of Rastafarianism. Jamaica has produced some of history's greatest sprinters, including Usain Bolt who set world records at the 2009 World Championships, and gained independence from Britain in 1962. The island is known for its Blue Mountains, vibrant markets, and jerk cuisine.",
  MX: "Mexico is one of the world's largest countries by area, located in southern North America, and Mexico City — built on the ancient Aztec capital Tenochtitlan — is one of the Western Hemisphere's largest and most historic cities. Mexico was the centre of major pre-Columbian civilisations including the Aztec and Maya empires, and today is the world's largest silver producer. Its culinary tradition has been recognised by UNESCO as Intangible Cultural Heritage of Humanity.",
  NI: "Nicaragua is the largest country in Central America by area, known as the 'Land of Lakes and Volcanoes' for its dramatic landscape. Lake Nicaragua contains freshwater sharks, which adapted from the ocean over thousands of years as the lake's ancient Pacific connection closed. Nicaragua gained independence from Spain in 1821 and was the site of significant revolutionary conflict in the late 1970s and 1980s.",
  PA: "Panama is located at the narrow isthmus connecting North and South America and is home to the Panama Canal, one of the world's most important engineering achievements, connecting the Pacific and Atlantic Oceans and handling around 5% of global trade. The canal was completed in 1914 and transferred to Panamanian sovereignty in 1999. Panama has extraordinary biodiversity, with more bird species than the continental United States and Canada combined.",
  PY: "Paraguay is a landlocked South American country bordered by Argentina, Brazil, and Bolivia, and is one of only two landlocked countries on the continent. Despite its landlocked status, it is a major electricity exporter from the Itaipú Dam, one of the world's largest hydroelectric power plants. Paraguay is notable for being the only country in the Americas where an indigenous language, Guaraní, is an official language alongside Spanish and is widely spoken by the majority of the population.",
  PE: "Peru is located in western South America and was the centre of the Inca Empire, the largest empire in pre-Columbian America, which at its peak stretched from present-day Colombia to Chile. Machu Picchu, the 15th-century Inca citadel perched at 2,430 metres in the Andes, is one of the world's most visited and photographed archaeological sites. Peru has extraordinary ecological diversity spanning the Andes mountains, the Amazon jungle (covering over 60% of the country), and a coastal desert.",
  KN: "Saint Kitts and Nevis is the smallest sovereign state in the Western Hemisphere by both area and population, a twin-island Caribbean nation in the Lesser Antilles. Saint Kitts was Britain's first Caribbean colony, established in 1623, and served as the base for subsequent colonisation of other islands. The island gained independence in 1983 and Brimstone Hill Fortress — a UNESCO World Heritage Site — stands as an impressive reminder of the colonial era.",
  LC: "Saint Lucia is a Caribbean island nation sometimes called 'Helen of the West Indies' because it was fought over so intensely that it changed hands between Britain and France fourteen times. The Pitons — two dramatic volcanic spires rising from the sea on the island's southwestern coast — are a UNESCO World Heritage Site. Saint Lucia is known for its rum production, jazz festival, and one of the highest densities of Nobel Prize winners per capita of any country in the world.",
  VC: "Saint Vincent and the Grenadines is a Caribbean island nation consisting of the main island of Saint Vincent and 32 smaller Grenadine islands and cays. The Grenadines — including Bequia and the Tobago Cays — are among the Caribbean's most sought-after sailing destinations. Saint Vincent is home to La Soufrière, an active volcano that erupted dramatically in 2021, and is one of the Caribbean's leading producers of arrowroot.",
  SR: "Suriname is the smallest sovereign country in South America by area and the only South American country where Dutch is the official language, a legacy of its colonial history as Dutch Guiana. More than 90% of its territory is covered by tropical rainforest, one of the most intact such ecosystems in the world. Paramaribo, the capital, has a historic inner city of Dutch colonial wooden architecture that is a UNESCO World Heritage Site.",
  TT: "Trinidad and Tobago is a twin-island Caribbean nation just off the northeastern coast of Venezuela and is the birthplace of two distinctive cultural contributions. Trinidad is the origin of the steelpan, the national instrument developed in the early 20th century from oil drums. It is also the birthplace of Caribbean Carnival as it developed, with Trinidad's annual Carnival renowned worldwide for its elaborate masquerade bands and calypso and soca music.",
  US: "The United States of America is the world's third-largest country by area and third-most-populous, a federal republic of 50 states that declared independence from Britain in 1776. It has been the world's largest economy for over a century and has dominated global political, military, and cultural influence in the modern era. The United States has made profound contributions to global science, technology, literature, music, and film, and hosts the world's most prestigious universities and research institutions.",
  UY: "Uruguay is the second-smallest country in South America and is consistently ranked as Latin America's most democratic, transparent, and socially progressive nation. It was the first country in Latin America to legalise same-sex marriage (2013) and the first in the world to fully legalise recreational cannabis (2013). Uruguay has a strong tradition of public education dating to the 19th century and a high level of human development relative to its regional neighbours.",
  VE: "Venezuela is located on the northern coast of South America and has the world's largest proven oil reserves, though managing this wealth has been a central challenge throughout its modern history. The country is home to Angel Falls (Salto Ángel), the world's highest uninterrupted waterfall at 979 metres, located in the Canaima National Park in the tepui highlands. Venezuela has an extraordinary ecological range encompassing the Andes, the Orinoco River delta, Caribbean beaches, and the unique table-top tepui mountains.",

  // ── OCEANIA ─────────────────────────────────────────────────────────────────
  AU: "Australia is the world's sixth-largest country by area and the only nation that governs an entire continent, a vast land with ecological diversity from tropical rainforests to scorching deserts to temperate forests. It is home to unique wildlife found nowhere else, including kangaroos, koalas, platypuses, wombats, and the world's two egg-laying mammals. The Great Barrier Reef, stretching 2,300 kilometres along the Queensland coast, is the world's largest coral reef system.",
  FJ: "Fiji is a South Pacific archipelago of more than 330 islands, of which about 110 are permanently inhabited, located northeast of New Zealand. The country is known for its crystal-clear lagoons, vibrant coral reefs, and a culture of warm hospitality centred around the greeting 'bula' (life, health, and happiness). Fiji has a diverse population of indigenous Fijians and Indo-Fijians descended from labourers brought by British colonial authorities, and has been independent since 1970.",
  KI: "Kiribati (pronounced 'Kiribas') is a Pacific island nation spanning three island groups across the central Pacific and is the world's only country to straddle all four hemispheres — north, south, east, and west. Its 33 atolls and one raised coral island are spread across an ocean area larger than India. Kiribati faces an existential threat from rising sea levels, with most of its land just one to two metres above sea level.",
  MH: "The Marshall Islands is an archipelago of 1,156 islands and islets in the central Pacific and was the site of multiple US nuclear weapons tests from 1946 to 1958, including the Castle Bravo test in 1954 — the largest US nuclear test ever conducted, more than 1,000 times the power of the Hiroshima bomb. The nation gained independence from US administration in 1986. Like Kiribati, the Marshall Islands faces a severe existential threat from rising sea levels.",
  FM: "The Federated States of Micronesia is an island group of 607 islands in the western Pacific, organised into four states: Yap, Chuuk, Pohnpei, and Kosrae. The islands were administered by the United States under a UN Trusteeship until independence in 1986. Micronesia is celebrated for its extraordinary marine biodiversity, particularly the Japanese WWII wrecks in Chuuk Lagoon, which attract scuba divers from around the world.",
  NR: "Nauru is the world's smallest island nation, a single oval-shaped island of just 21 square kilometres in the central Pacific, roughly halfway between Hawaii and Australia. In the 1970s, Nauru briefly had one of the world's highest per-capita incomes from phosphate mining, before deposits were exhausted and the island's interior left as a barren, strip-mined landscape. Today Nauru faces significant economic and environmental challenges and has the world's highest rates of obesity.",
  NZ: "New Zealand is an island country in the southwestern Pacific known for its dramatic and diverse landscapes of fjords, mountains, volcanoes, beaches, and geothermal areas — landscapes that served as the filming location for the Lord of the Rings trilogy. New Zealand was the first country in the world to grant women the right to vote, in 1893. The indigenous Māori culture, with its haka, whakairo (carving), and te reo Māori language, has a deep and growing influence on national identity.",
  PW: "Palau is an archipelago of more than 500 islands in the western Pacific, home to some of the world's most pristine marine ecosystems. Jellyfish Lake, where millions of jellyfish evolved without stingers due to the absence of predators, is one of Palau's most famous attractions. Palau gained independence from US administration in 1994 and has established some of the Pacific's strictest marine protection zones.",
  PG: "Papua New Guinea occupies the eastern half of the island of New Guinea and is one of the world's most linguistically diverse countries, with over 800 languages spoken by a population of around 9 million — more languages than any other country on Earth. The country has extraordinary biodiversity with large areas of intact tropical rainforest and species found nowhere else. Papua New Guinea achieved independence from Australian administration in 1975.",
  WS: "Samoa is a Polynesian island nation in the South Pacific consisting of two main islands and several smaller ones. It was the first Pacific Island country to gain independence, in 1962. Samoan culture is deeply centred on fa'a Samoa (the Samoan way), which emphasises community, family, and respect for elders. In 2011, Samoa shifted its position relative to the International Date Line to better align its trading week with Australia and New Zealand.",
  SB: "The Solomon Islands is an archipelago of nearly 1,000 islands in the southwestern Pacific and was the site of some of the Pacific War's most strategically significant battles during World War II, particularly the Guadalcanal campaign of 1942-43. The islands have extraordinary marine biodiversity with some of the healthiest coral reefs in the Pacific. The Solomon Islands gained independence from Britain in 1978.",
  TO: "Tonga is an archipelago kingdom of 169 islands in the South Pacific and is the last remaining Polynesian monarchy. It is the only Pacific nation never to have been fully colonised by a European power, maintaining sovereignty throughout the 19th century under the Tupou dynasty. Tongan culture has a passionate sporting tradition, particularly in rugby union, with the national team competing regularly in Rugby World Cups despite a population of just over 100,000.",
  TV: "Tuvalu is one of the world's smallest, most remote, and most threatened nations — a Polynesian island group in the central Pacific with a highest point of just 4.6 metres above sea level. The country faces an existential threat from rising sea levels caused by climate change, with much of its land at risk of flooding and saltwater intrusion. Tuvalu licences its highly sought-after '.tv' internet domain extension for significant revenue, providing crucial income for this tiny nation.",
  VU: "Vanuatu is an archipelago of 80 islands in the southwestern Pacific, gained independence from joint British-French colonial administration in 1980. It is notable for its extraordinary linguistic diversity — over 100 distinct local languages are spoken by a population of fewer than 300,000, giving it the world's highest concentration of languages per capita. Vanuatu is home to some of the world's most accessible active volcanoes, including Mount Yasur on Tanna island, where visitors can walk to the crater rim.",
}

export const CODEX: Record<string, CodexEntry> = Object.fromEntries(
  Object.entries(CODEX_SUMMARIES).map(([code, summary]) => [
    code,
    { code, summary, flagHistory: FLAG_HISTORY[code] ?? [] },
  ])
)
